{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise TypeError("case must be an object")

    for field in ("threshold", "calls"):
        if field not in case:
            raise ValueError("missing required field: " + field)

    threshold = case["threshold"]
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be a number")
    if not math.isfinite(threshold):
        raise ValueError("threshold must be finite")
    if threshold < 0:
        raise ValueError("threshold must be non-negative")

    calls = case["calls"]
    if not isinstance(calls, list):
        raise TypeError("calls must be a list")

    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )
    validated = []
    seen_ids = set()

    for index, call in enumerate(calls):
        if not isinstance(call, dict):
            raise TypeError("call at index %d must be an object" % index)
        for field in required:
            if field not in call:
                raise ValueError("call at index %d is missing required field: %s" % (index, field))

        call_id = call["call_id"]
        if not isinstance(call_id, str) or not call_id:
            raise TypeError("call_id at index %d must be a non-empty string" % index)
        if call_id in seen_ids:
            raise ValueError("duplicate call_id: " + call_id)
        seen_ids.add(call_id)

        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        for name, value in (("loss_without_call", loss_without), ("loss_with_call", loss_with)):
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("%s at index %d must be a number" % (name, index))
            if not math.isfinite(value):
                raise ValueError("%s at index %d must be finite" % (name, index))
            if value < 0:
                raise ValueError("%s at index %d must be non-negative" % (name, index))

        prediction_tokens = call["prediction_tokens"]
        if isinstance(prediction_tokens, bool) or not isinstance(prediction_tokens, int):
            raise TypeError("prediction_tokens at index %d must be an integer" % index)
        if prediction_tokens < 0:
            raise ValueError("prediction_tokens at index %d must be non-negative" % index)

        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise TypeError("parseable at index %d must be a boolean" % index)

        validated.append((call_id, float(loss_without), float(loss_with), prediction_tokens, parseable))

    accepted_call_ids = []
    diagnostics = []
    for call_id, loss_without, loss_with, prediction_tokens, parseable in validated:
        normalized_weight = 1.0 / max(1, prediction_tokens)
        weighted_loss_without = loss_without * normalized_weight
        weighted_loss_with = loss_with * normalized_weight
        gain = loss_without - loss_with
        normalized_gain = weighted_loss_without - weighted_loss_with
        accepted = parseable and normalized_gain >= threshold

        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append({
            "call_id": call_id,
            "gain": round(gain, 6),
            "normalized_gain": round(normalized_gain, 6),
            "accepted": accepted,
        })

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
"}
